//! User and address types that need serde support.

/// A user record.
#[derive(Debug, PartialEq)]
pub struct User {
    pub id: u64,
    pub name: String,
    pub email: String,
    pub active: bool,
}

/// An address.
#[derive(Debug, PartialEq)]
pub struct Address {
    pub street: String,
    pub city: String,
    /// Serialized as "postal_code" in JSON.
    pub zip: String,
    /// Serialized as "country_code" in JSON.
    pub country: String,
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json;

    #[test]
    fn test_user_serialize() {
        let u = User { id: 1, name: "Alice".into(), email: "a@b.com".into(), active: true };
        let json = serde_json::to_string(&u).unwrap();
        assert!(json.contains("\"id\":1"));
        assert!(json.contains("\"name\":\"Alice\""));
    }

    #[test]
    fn test_user_roundtrip() {
        let u = User { id: 42, name: "Bob".into(), email: "bob@example.com".into(), active: false };
        let json = serde_json::to_string(&u).unwrap();
        let u2: User = serde_json::from_str(&json).unwrap();
        assert_eq!(u, u2);
    }

    #[test]
    fn test_address_custom_field_names() {
        let a = Address { street: "123 Main".into(), city: "Springfield".into(),
                          zip: "12345".into(), country: "US".into() };
        let json = serde_json::to_string(&a).unwrap();
        // zip should be serialized as postal_code
        assert!(json.contains("\"postal_code\":\"12345\""));
        // country should be serialized as country_code
        assert!(json.contains("\"country_code\":\"US\""));
    }

    #[test]
    fn test_address_roundtrip() {
        let a = Address { street: "456 Oak".into(), city: "Shelbyville".into(),
                          zip: "99999".into(), country: "CA".into() };
        let json = serde_json::to_string(&a).unwrap();
        let a2: Address = serde_json::from_str(&json).unwrap();
        assert_eq!(a, a2);
    }
}
